"use client";
import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  ControlStyles,
  controlVariables,
  useControlTransition,
  useControlValue,
  type ControlAppearance,
} from "./control-shared";
export interface MorphingIslandSection {
  id: string;
  label: string;
  description: ReactNode;
  image?: { src: string; alt: string };
  content?: ReactNode /** Existing document target when renderSections is false. */;
  targetId?: string;
}
export interface MorphingIslandProps extends ControlAppearance {
  sections: readonly MorphingIslandSection[];
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string | undefined) => void;
  onNavigate?: (section: MorphingIslandSection) => void;
  label?: string;
  closeLabel?: string;
  backLabel?: string;
  actionLabel?: string /** Render a scoped scroll specimen; false attaches navigation to supplied document targets. */;
  renderSections?: boolean;
  fixed?: boolean;
}
export function MorphingIsland({
  sections,
  open,
  defaultOpen = false,
  onOpenChange,
  value,
  defaultValue,
  onValueChange,
  onNavigate,
  label = "Sections",
  closeLabel = "Close",
  backLabel = "Back",
  actionLabel = "Scroll to section",
  renderSections = true,
  fixed = false,
  ...appearance
}: MorphingIslandProps) {
  const [isOpen, setOpen] = useControlValue(open, defaultOpen, onOpenChange);
  const [detail, setDetail] = useControlValue<string | undefined>(
    value,
    defaultValue,
    onValueChange,
  );
  const [active, setActive] = useState(sections[0]?.id);
  const root = useRef<HTMLDivElement>(null);
  const capsule = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const id = useId();
  const transition = useControlTransition(appearance.duration);
  const reduce = useReducedMotion();
  const section = sections.find((s) => s.id === detail);
  useEffect(() => {
    if (!isOpen) return;
    const dismiss = (event: PointerEvent) => {
      if (!capsule.current?.contains(event.target as Node)) setOpen(false);
    };
    const escape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false);
        trigger.current?.focus();
      }
    };
    document.addEventListener("pointerdown", dismiss);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("pointerdown", dismiss);
      document.removeEventListener("keydown", escape);
    };
  }, [isOpen, setOpen]);
  useEffect(() => {
    if (typeof IntersectionObserver === "undefined") return;
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible) setActive(visible.target.getAttribute("data-section-id") ?? visible.target.id);
      },
      { root: renderSections ? root.current : null, threshold: [0.3, 0.6, 0.8] },
    );
    sections.forEach((s) => {
      const el = document.getElementById(renderSections ? `${id}-${s.id}` : (s.targetId ?? s.id));
      if (el) observer.observe(el);
    });
    return () => observer.disconnect();
  }, [sections, renderSections, id]);
  function navigate(s: MorphingIslandSection) {
    document
      .getElementById(renderSections ? `${id}-${s.id}` : (s.targetId ?? s.id))
      ?.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });
    setActive(s.id);
    setOpen(false);
    onNavigate?.(s);
    trigger.current?.focus();
  }
  const navigation = (
    <div className="z-mc-island-anchor" style={fixed ? { position: "fixed" } : undefined}>
      <motion.nav
        layout
        className="z-mc-island-capsule"
        ref={capsule}
        data-state={!isOpen ? "closed" : section ? "detail" : "menu"}
        aria-label={label}
        transition={transition}
      >
        <div className="z-mc-island-top">
          <button
            type="button"
            ref={trigger}
            aria-expanded={isOpen}
            aria-controls={`${id}-navigation`}
            aria-label={label}
            onClick={() => {
              setDetail(undefined);
              setOpen(!isOpen);
            }}
          >
            {isOpen ? label : (sections.find((s) => s.id === active)?.label ?? label)}
          </button>
          {isOpen ? (
            <button
              type="button"
              onClick={() => {
                setOpen(false);
                trigger.current?.focus();
              }}
            >
              {closeLabel}
            </button>
          ) : (
            <span aria-hidden="true">⌄</span>
          )}
        </div>
        <AnimatePresence initial={false} mode="wait">
          {isOpen && (
            <motion.div
              key={section?.id ?? "menu"}
              id={`${id}-navigation`}
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={transition}
            >
              {section ? (
                <div className="z-mc-island-detail">
                  <button
                    className="z-mc-island-back"
                    type="button"
                    onClick={() => setDetail(undefined)}
                  >
                    ← {backLabel}
                  </button>
                  <h3>{section.label}</h3>
                  <p>{section.description}</p>
                  <button
                    type="button"
                    className="z-mc-island-jump"
                    onClick={() => navigate(section)}
                  >
                    {actionLabel} ↗
                  </button>
                </div>
              ) : (
                <div className="z-mc-island-list">
                  {sections.map((s, index) => (
                    <button key={s.id} type="button" onClick={() => setDetail(s.id)}>
                      <small>{String(index + 1).padStart(2, "0")}</small>
                      <span>{s.label}</span>
                      {active === s.id && <i aria-label="Current section">•</i>}
                    </button>
                  ))}
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.nav>
    </div>
  );
  return (
    <>
      <ControlStyles />
      <div
        className={`z-mc ${renderSections ? "z-mc-island" : ""} ${appearance.className ?? ""}`}
        style={controlVariables(appearance)}
      >
        {renderSections && (
          <div ref={root} className="z-mc-island-scroll">
            {sections.map((s, index) => (
              <section
                className="z-mc-island-section"
                data-section-id={s.id}
                id={`${id}-${s.id}`}
                key={s.id}
              >
                {s.image && <img src={s.image.src} alt={s.image.alt} />}
                <small>{String(index + 1).padStart(2, "0")}</small>
                <div>
                  <h2>{s.label}</h2>
                  {s.content}
                </div>
              </section>
            ))}
          </div>
        )}
        {navigation}
      </div>
    </>
  );
}
